mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join Sec_Solicitation_Notice sn on sn.Sec_Id = sec.Sec_Id where sn.id = #{id}

select
sec.Sec_Name as secName,
sec.Sec_Type as secType,
c1.C_Name    as secTendereeName,
c2.C_Name    as snProcureCpyName,
mn.*
from Sec_Solicitation_Notice mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id
left join Sys_Company c1 on c1.C_Id = sec.Sec_Tenderee
left join Sys_Company c2 on c2.C_Id = mn.Sn_Procure_Cpy

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Sn_Quotation_Method=#{params.snQuotationMethod}
    
    
        and mn.Sn_Settlement_Method=#{params.snSettlementMethod}
    
    
        and mn.State=#{params.state}
    
    
        and mn.Sec_Id=#{params.secId}
    
    
        and mn.Sn_Calibration=#{params.snCalibration}
    
    
        and INSTR(mn.Sn_Procure_Person,#{params.snProcurePerson})
    
    
        and INSTR(mn.Sn_Procure_Phone,#{params.snProcurePhone})
    
    
        and INSTR(mn.Sn_Agency_Cpy,#{params.snAgencyCpy})
    
    
        
            
                and likeCname(#{params.snProcureCpyName},c2.C_Id)=true
            
            
                and INSTR(c2.C_Name,#{params.snProcureCpyName})
            
        
    
    
        and INSTR(sec.Sec_Name,#{params.secName})
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
